const r = await tools.exec_command({cmd:"printf 'TARGET=%s\nOUTPUT=%s\nRUNNER=%s\nPYTHON=%s\n' "$STAMPED_JUDGE_TARGET" "$STAMPED_JUDGE_OUTPUT" "$STAMPED_ASSESSMENT_RUNNER" "$STAMPED_ASSESSMENT_PYTHON"
git -C "$STAMPED_JUDGE_TARGET" rev-parse HEAD
pwd
",yield_time_ms:10000,max_output_tokens:2000});
text(r.output);

const results = await Promise.all([
  tools.exec_command({cmd:"\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" fresh-rerun --url https://hub.centerforopenneuroscience.org/leej3/stamped-ai-research-next.git --entry 'pixi run git annex get input/data && pixi run recorded-analysis' --outputs 'results/*.nii.gz' 'results/*.tsv' 'results/*.json' 'results/*.png' 'results/report.md' --workdir \"$STAMPED_JUDGE_OUTPUT/fresh-clone\" -o \"$STAMPED_JUDGE_OUTPUT/2026-10-16-fresh-rerun.json\"",yield_time_ms:1000,max_output_tokens:3000}),
  tools.exec_command({cmd:"jq '{summary, probes: [.probes[] | {name,status,items,details}]}' \"$STAMPED_JUDGE_OUTPUT/2026-10-16-probes.json\" | head -c 16000",yield_time_ms:10000,max_output_tokens:5000}),
  tools.exec_command({cmd:"git -C \"$STAMPED_JUDGE_TARGET\" config --get-regexp '^(remote\\.|annex\\.)' | sed -E 's/(token|password|secret)=.*/\\1=[redacted]/I'\ngit -C \"$STAMPED_JUDGE_TARGET\" annex whereis --json --key -- input/data/sub-001_hypo1_cope.nii.gz\ngit -C \"$STAMPED_JUDGE_TARGET\" annex whereis --json --key -- input/data/sub-123_hypo1_cope.nii.gz",yield_time_ms:10000,max_output_tokens:2500}),
  tools.exec_command({cmd:"grep -nE 'permutation|sign|mask|finite|vmPFC|variance|p_value|percentile|bootstrap' \"$STAMPED_JUDGE_TARGET/scripts/analyze.py\"\ncat \"$STAMPED_JUDGE_TARGET/logs/20261015T233701Z-provenance.json\" | jq '{execution_summary, output_paths, environment, command, working_directory}'\n",yield_time_ms:10000,max_output_tokens:4000})
]);
for (let i=0;i<results.length;i++) text(`--- RESULT ${i+1} ---\n${results[i].output}${results[i].session_id ? `\nSESSION_ID=${results[i].session_id}` : ""}`);

const r = await tools.exec_command({cmd:"jq 'keys' "$STAMPED_JUDGE_TARGET/logs/20261015T233701Z-provenance.json"
jq '{code_revision,pixi_manifest_sha256,pixi_lock_sha256,inputs,outputs,environment,execution_summary,command,run_id}' "$STAMPED_JUDGE_TARGET/logs/20261015T233701Z-provenance.json"
sed -n '1,240p' "$STAMPED_JUDGE_TARGET/scripts/write_run_record.py"
cat "$STAMPED_JUDGE_TARGET/logs/replay-compare-final-20261015-stdout"
",yield_time_ms:10000,max_output_tokens:5000});
text(r.output);

const r = await tools.exec_command({cmd:""$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response stamp "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json" --harness 'Codex API' --model 'GPT-6 (exact deployment unavailable)' --kind study --dependency 'stamped-conventions@0.1.0' --dependency 'assessment-runner (coordinator-pinned; see runner check output)' --scope 'Commit 8b5bcdaa; worker-stop receipt verified. Hub URL resolves to parent main, not this commit; local fresh clone failed retrieving 54 annex maps, so replay was blocked. Scientific review used retained artifacts.'
"$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response decode --help
"$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" validate --help
",yield_time_ms:10000,max_output_tokens:3000});
text(r.output);

const r = await tools.exec_command({cmd:"cat "$STAMPED_JUDGE_OUTPUT/2026-10-16-table.md"
jq '{object,assessor,scope,counts:(.responses|to_entries|group_by(.value.status)|map({status:.[0].value.status,count:length})),long_reasons:[.responses|to_entries[]|select((.value.reason|length)>250)|{id:.key,len:(.value.reason|length)}],empty_evidence:[.responses|to_entries[]|select(.value.status!="not-applicable" and (.value.evidence|length)==0)|.key],flags:[.responses|to_entries[]|select((.value.flags|length)>0)|{id:.key,flags:.value.flags}]}' "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json"
cat "$STAMPED_JUDGE_OUTPUT/2026-10-16-url.txt" | wc -c
cat "$STAMPED_JUDGE_OUTPUT/2026-10-16-fresh-rerun.json" | jq '{source,status,reason,outputs_count:(.outputs_shipped|length),failed_get_count:([.steps[]|select(.step|startswith("datalad get -r"))|.log]|join("\n")|[splits("\n")[]|select(test("get\\(error\\): input/data/"))]|length)}'
",yield_time_ms:10000,max_output_tokens:7000});
text(r.output);

const r = await tools.exec_command({cmd:""$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" response template -o "$STAMPED_JUDGE_OUTPUT/date-probe-template.json"
jq '{assessor,object}' "$STAMPED_JUDGE_OUTPUT/date-probe-template.json"
date -u +%F
",yield_time_ms:10000,max_output_tokens:1500});
text(r.output);

const r = await tools.exec_command({cmd:"read -r assessment_date < <(date -u +%F)
"$STAMPED_ASSESSMENT_PYTHON" -c 'import json,sys; p=sys.argv[1]; d=sys.argv[2]; x=json.load(open(p)); x["assessor"]["date"]=d; json.dump(x,open(p,"w"),indent=2); open(p,"a").write("\n")' "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json" "$assessment_date"
"$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" validate "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json"
jq '{date:.assessor.date,kind:.object.kind,commit:.object.commit}' "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json"
",yield_time_ms:10000,max_output_tokens:1000});
text(r.output);

const r = await tools.exec_command({cmd:"git -C "$STAMPED_JUDGE_TARGET" ls-remote --heads con-hub > "$STAMPED_JUDGE_OUTPUT/2026-10-16-remote-check.txt"
git -C "$STAMPED_JUDGE_TARGET" remote -v >> "$STAMPED_JUDGE_OUTPUT/2026-10-16-remote-check.txt"
cat "$STAMPED_JUDGE_OUTPUT/2026-10-16-remote-check.txt"
",yield_time_ms:10000,max_output_tokens:1200});
text(r.output);

const r = await tools.exec_command({cmd:""$STAMPED_ASSESSMENT_PYTHON" -c 'from pathlib import Path; import shutil; root=Path("."); names=["2026-10-16-decoded.json","2026-10-16-table.md","2026-10-16-template.json","date-probe-template.json","fresh-clone","replay-local"]; [(shutil.rmtree(root/n) if (root/n).is_dir() else (root/n).unlink(missing_ok=True)) for n in names]' "$STAMPED_JUDGE_OUTPUT"
git -C "$STAMPED_JUDGE_TARGET" status --short --branch
git -C "$STAMPED_JUDGE_OUTPUT" status --short
",yield_time_ms:10000,max_output_tokens:1200});
text(r.output);

const r = await tools.exec_command({cmd:"rg -n '^\| must/016|^\*\*MUST|must/016` —|No required artifacts' "$STAMPED_JUDGE_OUTPUT/2026-10-16-assessment.md"
jq '{date:.assessor.date,counts:(.responses|to_entries|group_by(.value.status)|map({status:.[0].value.status,count:length})), must016:.responses["stamped-checklist:must/016"]}' "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json"
"$STAMPED_ASSESSMENT_PYTHON" "$STAMPED_ASSESSMENT_RUNNER" validate "$STAMPED_JUDGE_OUTPUT/2026-10-16-response.json"
",yield_time_ms:10000,max_output_tokens:1500});
text(r.output);

const r = await tools.exec_command({cmd:"shasum -a 256 /Users/johnlee/.local/state/stamped-ai-research-next/preparation-20261015/cold-stamped-op-evidence/judgment-01/worker-end-state.json
git -C "$STAMPED_JUDGE_TARGET" rev-parse HEAD
git -C "$STAMPED_JUDGE_TARGET" status --short
jq -r '.status, .reason' "$STAMPED_JUDGE_OUTPUT/2026-10-16-fresh-rerun.json"
",yield_time_ms:10000,max_output_tokens:1000});
text(r.output);
